#!/usr/bin/env bash
# Builds the archive uploaded to PlayForward as the em2coop mod:
#
#   binkw32.dll            the proxy (the game's own is kept as binkw32_real.dll)
#   em2coop.ini            options, all defaults
#   playforward-mod.json   install instructions: required build, kept original,
#                          and the game data files to patch
#   patches/*.vcdiff       those patches (never the game's own files)
#
# The instructions and patches are regenerated by tools/make_patches.py.
#
#   ./package.sh [version]     -> dist/em2coop-<version>.zip
set -euo pipefail

cd "$(dirname "$0")"
version="${1:-$(git describe --tags --always --dirty 2>/dev/null || echo dev)}"
archive="dist/em2coop-${version}.zip"

./build.sh

stage="$(mktemp -d)"
trap 'rm -rf "$stage"' EXIT
cp build/binkw32.dll em2coop.ini "$stage/"
cp -r playforward/. "$stage/"

mkdir -p dist
rm -f "$archive"
# -X: no extra attributes, -D: no directory entries; paths are relative to
# the game folder, as PlayForward extracts them.
(cd "$stage" && zip -X -D -r -q "$OLDPWD/$archive" .)

echo "packaged $archive ($(stat -c %s "$archive") bytes)"
unzip -l "$archive"
